<template><el-dialog v-model="visible" title="物料明细" width="900px" class="storage-dialog material-line-dialog" append-to-body :close-on-click-modal="false" :before-close="close"><el-form label-position="top" :disabled="saving||reservationPending"><div class="storage-grid">
 <el-form-item v-if="groupedPicking" label="客户 / 库存物料" required><el-select v-model="selectedKey" aria-label="库存物料" filterable @change="selectGroup"><el-option v-if="line.stockId&&!selectedGroup" :value="selectedKey" label="原来源已不可用，请重新选择客户物料" disabled/><el-option v-for="g in groups" :key="g.key" :value="g.key" :label="groupLabel(g)"/></el-select></el-form-item>
 <el-form-item v-else-if="usesStock" label="库存物料 / 批次" required><el-select v-model="line.stockId" aria-label="库存物料" filterable @change="selectStock"><el-option v-if="line.stockId&&!stock" :value="line.stockId" :label="`${line.name||line.code||'原库存'}（不可用于本次领料，请重新选择）`" disabled/><el-option v-for="s in stocks" :key="s.id" :label="`【${stockCategories[s.category]||'库存'}】 ${s.identity?.code||s.code||''} / ${s.identity?.name||s.identity?.materialType||s.name||s.materialType||''} / ${s.batchNo||s.id} / 可用${s.availableWeight??s.netWeight}g${s.measurementMode==='PIECE'?` / ${s.availableQuantity??s.quantity}件`:''}`" :value="s.id"/></el-select></el-form-item>
 <el-form-item v-if="!usesStock&&!['SEMI_IN','PRODUCT_IN','EXTERNAL_SEMI_IN'].includes(type)" label="产出 / 入库物料" required><el-select v-model="line.materialId" aria-label="入库物料" filterable @change="selectMaterial"><el-option v-for="m in state.materials" :key="m.id" :label="`【原料】 ${m.code||''} / ${m.name||m.materialType||''}`" :value="m.id"/></el-select></el-form-item>
 <el-form-item v-if="['SEMI_IN','PRODUCT_IN','EXTERNAL_SEMI_IN'].includes(type)" label="产品" required><el-select v-model="line.productId" aria-label="产品" filterable @change="selectProduct"><el-option v-for="p in state.products" :key="p.id" :label="`【${type==='PRODUCT_IN'?'成品':'半成品'}】 ${p.code||''} / ${p.name}`" :value="p.id"/></el-select></el-form-item>
 <el-form-item v-if="['RAW_IN','CUSTOMER_IN','EXTERNAL_SEMI_IN','ADJUSTMENT','OWNERSHIP_RETURN'].includes(type)" :label="type==='OWNERSHIP_RETURN'?'还料来源料权':'料权归属'" required><div class="owner-control"><el-select v-model="line.ownerId" aria-label="料权归属" :disabled="type==='OWNERSHIP_RETURN'&&!!line.borrowOwnerId"><el-option label="工厂" value="0"/><el-option v-for="c in state.customers" :key="c.id" :label="c.companyName||c.name" :value="c.id"/></el-select><el-button v-if="['RAW_IN','EXTERNAL_SEMI_IN'].includes(type)&&can('metal:customer:add')" type="primary" @click="openCustomer">添加客户</el-button></div></el-form-item>
 <el-form-item v-if="type==='EXTERNAL_SEMI_IN'" label="外部来源凭证" required><el-input v-model="line.externalSource.sourceReference" maxlength="200"/></el-form-item>
 <el-form-item v-if="type==='EXTERNAL_SEMI_IN'" label="已完成至工序" required><el-select :model-value="completedUntil" @change="setCompleted"><el-option v-for="(step,index) in externalSteps" :key="step.id" :value="index+1" :label="`${index+1}. ${step.name}`"/></el-select></el-form-item>
 <el-form-item v-if="['RAW_RETURN','RECOVERY_RETURN'].includes(type)" label="原领料明细ID" required><el-select v-model="line.issueLineId" :loading="issueLoading" :disabled="issueLoading" filterable @change="selectIssue" placeholder="选择本批次原领料"><el-option v-for="r in issueLines" :key="r.id" :label="`${r.documentNumber||''} / ${r.name||r.id}`" :value="r.id"/></el-select></el-form-item>
 <el-form-item v-if="!usesStock&&!['SEMI_IN','PRODUCT_IN','EXTERNAL_SEMI_IN'].includes(type)" label="物料形态"><el-select v-model="line.form"><el-option label="粉料" value="POWDER"/><el-option label="未处理料" value="UNTREATED"/><el-option label="金属料" value="METAL"/></el-select></el-form-item>
 <el-form-item v-if="type!=='ADJUSTMENT'" label="纯度（%）"><el-input v-model="line.purity" inputmode="decimal"/></el-form-item>
 <el-form-item v-if="type!=='ADJUSTMENT'" label="毛重（g）"><el-input v-model="line.grossWeight" inputmode="decimal"/></el-form-item>
 <el-form-item v-if="type!=='ADJUSTMENT'" label="杂质（g）"><el-input v-model="line.impurity" inputmode="decimal"/></el-form-item>
 <el-form-item v-if="type!=='ADJUSTMENT'" label="实测净重（g）" required><el-input v-model="line.netWeight" aria-label="实测净重（g）" inputmode="decimal" @blur="line.netWeight=format(line.netWeight)"/></el-form-item>
 <el-form-item v-if="type!=='ADJUSTMENT'&&measurement==='PIECE'" label="数量（件）" required><el-input v-model="line.quantity" aria-label="数量（件）" inputmode="numeric"/></el-form-item>
 <el-form-item v-if="type!=='ADJUSTMENT'&&type==='PRODUCT_IN'&&measurement==='WEIGHT'" label="参考完工件数" required><el-input v-model="line.referenceQuantity" inputmode="numeric"/></el-form-item>
 <el-form-item v-if="type==='RAW_RETURN'&&measurement==='PIECE'" label="工厂料实测归还重量（g）"><el-input v-model="line.factoryWeight" inputmode="decimal" placeholder="混合料权须填写实测份额"/></el-form-item>
 <el-form-item v-if="type==='ADJUSTMENT'" label="调整净重增减（g）" required><el-input v-model="line.deltaWeight" inputmode="decimal" placeholder="增加填正数，减少填负数"/></el-form-item>
 <el-form-item v-if="type==='ADJUSTMENT'&&measurement==='PIECE'" label="调整件数增减" required><el-input v-model="line.deltaQuantity" inputmode="numeric"/></el-form-item>
 <el-form-item label="备注 / 原因" class="wide" :required="type==='ADJUSTMENT'"><el-input v-model="line.remark" type="textarea" maxlength="500"/></el-form-item>
 </div><section v-if="type==='PRODUCTION_OUT'&&stock&&!groupedPicking" :class="line.allocations.length?'allocation-section':'allocation-add'"><div class="allocation-heading"><h3 v-if="line.allocations.length">领料来源分配</h3><el-button class="list-action list-action--primary list-action--row" @click="line.allocations.push({ownerId:'',weight:'',quantity:''})">添加来源</el-button></div><el-table v-if="line.allocations.length" :data="line.allocations" border class="allocation-table"><el-table-column label="料权方"><template #default="{row}"><el-select v-model="row.ownerId" aria-label="来源料权方"><el-option v-for="o in sourceOwners" :key="o.id" :label="o.label" :value="o.id" :disabled="o.disabled"/></el-select></template></el-table-column><el-table-column label="净重（g）"><template #default="{row}"><el-input v-model="row.weight"/></template></el-table-column><el-table-column v-if="measurement==='PIECE'" label="件数"><template #default="{row}"><el-input v-model="row.quantity"/></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button class="list-action list-action--delete list-action--row" type="danger" @click="line.allocations=line.allocations.filter((x:any)=>x!==row)">移除</el-button></template></el-table-column></el-table></section>
 <template v-if="type==='OWNERSHIP_RETURN'"><h3>原欠料核销明细</h3><p>选择原债务办理归还；借其他客户料还工厂所欠材料时，选择出借客户后自动使用其料权。材料规格、纯度和阶段须匹配原欠料。</p><el-table :data="line.debtAllocations" border><el-table-column label="原欠料"><template #default="{row}"><el-select v-model="row.debtId"><el-option v-for="d in debts" :disabled="d.status!=='OPEN'" :key="d.id" :label="`${d.id} / ${d.debtorName||d.debtorId}欠${d.creditorName||d.creditorId} / ${d.identity?.name||''} / 未还${d.remainingWeight}g${d.measurementMode==='PIECE'?` / ${d.remainingQuantity}件`:''}`" :value="d.id"/></el-select></template></el-table-column><el-table-column label="归还净重（g）"><template #default="{row}"><el-input v-model="row.weight"/></template></el-table-column><el-table-column v-if="measurement==='PIECE'" label="归还件数"><template #default="{row}"><el-input v-model="row.quantity"/></template></el-table-column></el-table><el-button @click="line.debtAllocations.push({debtId:'',weight:'',quantity:''})">添加核销记录</el-button><el-form-item label="借用其他客户料权归还（可选）"><el-select v-model="line.borrowOwnerId" clearable @change="changeBorrowOwner"><el-option v-for="c in state.customers" :key="c.id" :value="c.id" :label="c.name"/></el-select></el-form-item></template>
 </el-form><div v-if="issueError" class="issue-load-error"><el-alert :title="issueError" type="error" :closable="false"/><el-button :loading="issueLoading" @click="loadIssueLines">重试</el-button></div><div v-if="debtError" class="issue-load-error"><el-alert :title="debtError" type="error" :closable="false"/><el-button :loading="debtLoading" @click="loadDebts">重试</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div v-if="reservationPending" class="issue-load-error"><span>{{reservationError}}</span><el-button @click="emit('verifyReservation')">核实预占结果</el-button><el-button v-if="reservationRetry" @click="emit('retryReservation')">重试原请求</el-button></div><template #footer><el-button :disabled="saving||reservationPending" @click="close()">取消</el-button><el-button type="primary" :loading="saving" :disabled="reservationPending||issueLoading||!!issueError||debtLoading||!!debtError" @click="save">确认</el-button></template><CustomerCreateDialog v-model="customerOpen" :factory-id="state.factoryId" :factory-name="state.factories.find(f=>f.id===state.factoryId)?.name||''" :is-context-current="customerCurrent" :find-customers="findCustomers" @created="createdCustomer"/></el-dialog></template>
<script setup lang="ts">
import {stockGroups,splitStockGroup,weightText} from './stock-groups'
import CustomerCreateDialog from '@/components/CustomerCreateDialog/index.vue';import {computed,ref} from 'vue';import {ElMessageBox} from 'element-plus';import request from '@/utils/request';import {useStorage,uid,message,type Row} from '../storage-live/client';import {decimalValid,quantityValid,clone} from './model';import {roundDecimal,optionalPurityValid,purityError} from '@/utils/business-decimal'
const props=defineProps<{type:string;warehouseId:string;customerId?:string;executionId?:string;debt?:Row;confirmLine?:(line:any)=>Promise<void>;confirmGroup?:(lines:any[],groupId:string)=>Promise<void>;refreshOptions?:()=>Promise<void>;reservationPending?:boolean;reservationError?:string;reservationRetry?:boolean;confirmedLines?:any[]}>(),emit=defineEmits<{save:[any];verifyReservation:[];retryReservation:[]}>(),{state,context,can,loadOptions}=useStorage(),visible=ref(false),line=ref<any>({}),error=ref(''),debts=ref<Row[]>([]),issueLines=ref<Row[]>([]);const issueLoading=ref(false),issueError=ref(''),debtLoading=ref(false),debtError=ref('');let issueEpoch=0;let initial='',loadEpoch=0
const selectedKey=ref('')
const groupedPicking=computed(()=>props.type.endsWith('_OUT')&&!(line.value.allocations?.length>1))
const groups=computed(()=>stockGroups(stocks.value,props.type,props.customerId))
const selectedGroup=computed(()=>groups.value.find(g=>g.key===selectedKey.value))
const saving=ref(false);const customerOpen=ref(false);let customerContext=''
function openCustomer(){customerContext=context();customerOpen.value=true}
const customerCurrent=()=>visible.value&&customerContext===context()
async function findCustomers(current:()=>boolean){const r:any=await request({url:'/metal/options/customers',params:{factoryId:state.factoryId},quiet:true});return current()?r.data||[]:[]}
async function createdCustomer(value:{id:string;factoryId:string}){if(!customerCurrent())return;line.value.ownerId=value.id;customerOpen.value=false;await loadOptions({executionId:props.executionId})}
const stockCategories:Record<string,string>={RAW:'原料',SEMI:'半成品',PRODUCT:'成品'}
const usesStock=computed(()=>props.type.endsWith('_OUT')||['RAW_RETURN','RECOVERY_RETURN','ADJUSTMENT','OWNERSHIP_RETURN'].includes(props.type))
const stocks=computed(()=>{const rows=state.stocks.map(s=>remainingStock(s));for(const issue of issueLines.value){const source=issue.sourceStock||{id:issue.stockId,warehouseId:issue.warehouseId,materialId:issue.materialId,measurementMode:issue.measurementMode,identity:issue.identity,netWeight:issue.remainingWeight};if(source.id&&!rows.some(r=>String(r.id)===String(source.id)))rows.push({...source,id:String(source.id)})}return rows.filter(s=>(props.type!=='PRODUCTION_OUT'||['RAW','SEMI'].includes(s.category))).filter(s=>(props.type!=='RAW_OUT'||s.category==='RAW')&&(props.type!=='PRODUCT_OUT'||s.category==='PRODUCT')&&(props.type!=='SEMI_OUT'||s.category==='SEMI')).filter(s=>['RAW_RETURN','RECOVERY_RETURN'].includes(props.type)||String(s.warehouseId)===props.warehouseId)}),stock=computed(()=>groupedPicking.value&&selectedGroup.value?selectedGroup.value.members[0].stock:stocks.value.find(s=>s.id===line.value.stockId)),material=computed(()=>state.materials.find(m=>m.id===line.value.materialId)),measurement=computed(()=>stock.value?.measurementMode||state.executions.find(e=>e.id===props.executionId)?.measurementMode||(props.type==='EXTERNAL_SEMI_IN'?externalSteps.value[(completedUntil.value||0)-1]?.measurementMode:material.value?.measurementMode))
// Options exclude this editor's holds; subtract its other confirmed lines for the current row.
function remainingStock(stock:Row){
 if(!props.type.endsWith('_OUT'))return stock
 const siblings=(props.confirmedLines||[]).filter(l=>l.localId!==line.value.localId&&(!line.value.selectionGroupId||l.selectionGroupId!==line.value.selectionGroupId)&&String(l.stockId)===String(stock.id))
 const remaining=(value:unknown,amounts:unknown[],pieces=false)=>{
  if(value==null)return value
  const units=(v:unknown)=>BigInt(pieces?String(v??0):roundDecimal(v??0).replace('.',''))
  const n=amounts.reduce<bigint>((a,v)=>a-units(v),units(value)),positive=n>0n?n:0n
  return pieces?String(positive):`${positive/100n}.${String(positive%100n).padStart(2,'0')}`
 }
 return {...stock,availableWeight:remaining(stock.availableWeight??stock.netWeight,siblings.map(l=>l.netWeight)),availableQuantity:remaining(stock.availableQuantity??stock.quantity,siblings.map(l=>l.quantity),true),ownerships:(stock.ownerships||[]).map((owner:any)=>{
  const allocations=siblings.flatMap(l=>l.allocations?.length?l.allocations:[{ownerId:l.customerId,weight:l.netWeight,quantity:l.quantity}]).filter(a=>String(a.ownerId)===String(owner.ownerId))
  return {...owner,availableWeight:remaining(owner.availableWeight??owner.weight,allocations.map(a=>a.weight)),availableQuantity:remaining(owner.availableQuantity??owner.quantity,allocations.map(a=>a.quantity),true)}
 })}
}
const sourceOwners=computed(()=>{
 const owners=(stock.value?.ownerships||[]).map((o:any)=>{const id=String(o.ownerId),available=Number(measurement.value==='PIECE'?(o.availableQuantity??o.quantity):(o.availableWeight??o.weight))>0;return {id,disabled:!available,label:id==='0'&&!available?'工厂自有（当前批次无可用库存）':`${id==='0'?'工厂自有':o.ownerName||id}（${measurement.value==='PIECE'?`${o.availableQuantity??o.quantity}件 / `:''}${o.availableWeight??o.weight}g）`}})
 if(!owners.some((o:any)=>o.id==='0'))owners.unshift({id:'0',disabled:true,label:'工厂自有（当前批次无可用库存）'})
 return owners
})
const externalSteps=computed(()=>state.products.find(p=>p.id===line.value.productId)?.processes||[]),completedUntil=computed(()=>line.value.externalSource?.completedProcessIds?.length||null)
function setCompleted(n:number){line.value.externalSource.completedProcessIds=externalSteps.value.slice(0,n).map((s:any)=>String(s.processId||s.id))}
const format=(value:string)=>decimalValid(value)?roundDecimal(value):value
async function open(row?:any){selectedKey.value='';const round=++loadEpoch;line.value=row?{allocations:[],debtAllocations:[],externalSource:{sourceReference:'',completedProcessIds:[]},...clone(row)}:{localId:uid(),warehouseId:props.warehouseId,externalSource:{sourceReference:'',completedProcessIds:[]},stockId:'',materialId:'',productId:'',ownerId:props.type==='OWNERSHIP_RETURN'&&props.debt?String(props.debt.debtorId):'0',netWeight:'',quantity:'',grossWeight:'',impurity:'',purity:'',remark:'',form:'',deltaWeight:'',deltaQuantity:'',allocations:[],debtAllocations:props.debt?[{debtId:props.debt.id,weight:'',quantity:''}]:[]};if(props.type==='ADJUSTMENT')line.value.remark=line.value.reason||line.value.remark||'';if(props.type!=='EXTERNAL_SEMI_IN')delete line.value.externalSource;line.value.allocations=line.value.allocations.map((a:any)=>({...a,ownerId:a.ownerId==null?'':String(a.ownerId)}));if(!row){const execution=state.executions.find(e=>e.id===props.executionId);if(execution){line.value.productId=String(execution.expectedProductId||'');line.value.materialId=String(execution.outputMaterialId||'');if(line.value.materialId)selectMaterial()}}if(['SEMI_IN','PRODUCT_IN','EXTERNAL_SEMI_IN'].includes(props.type)&&(!row||!line.value.name))selectProduct();error.value='';issueError.value='';issueLoading.value=false;debtLoading.value=false;debtError.value='';debts.value=[];issueLines.value=[];initial=JSON.stringify(line.value);visible.value=true;const current=context();try{if(props.type.endsWith('_OUT')){await props.refreshOptions?.();if(round!==loadEpoch||!visible.value||current!==context())return;if(row){const owner=String(row.selectionOwnerId??row.allocations?.[0]?.ownerId??props.customerId??'0');selectedKey.value=groups.value.find(g=>g.key===row.selectionKey||g.ownerId===owner&&g.members.some(m=>String(m.stock.id)===String(row.stockId)))?.key||''}}if(props.type==='OWNERSHIP_RETURN')await loadDebts();if(['RAW_RETURN','RECOVERY_RETURN'].includes(props.type))await loadIssueLines()}catch(e){if(round===loadEpoch&&visible.value)error.value=message(e)}}
function changeBorrowOwner(value:string){const debt=debts.value.find(d=>String(d.id)===String(line.value.debtAllocations[0]?.debtId))||props.debt;line.value.ownerId=value?String(value):String(debt?.debtorId??'0')}
async function loadDebts(){
 const session=loadEpoch,current=context();debtLoading.value=true;debtError.value=''
 const active=()=>session===loadEpoch&&current===context()&&visible.value
 try{
  const selected=[...new Set<string>(line.value.debtAllocations.map((a:any)=>String(a.debtId)).filter((id:string)=>id))]
  const customer=props.debt?(String(props.debt.debtorId)==='0'?props.debt.creditorId:props.debt.debtorId):undefined
  const [result,details]:any[]=await Promise.all([
   request({url:'/metal/material-debts/list',params:{factoryId:state.factoryId,customerId:customer,direction:props.debt?(String(props.debt.debtorId)==='0'?'FACTORY_OWES':'CUSTOMER_OWES'):undefined,orderId:props.debt?.workOrderId||undefined,pageNum:1,pageSize:500},quiet:true}),
   Promise.all(selected.map(id=>request({url:`/metal/material-debts/${id}`,params:{factoryId:state.factoryId},quiet:true})))
  ])
  if(active()){
   const options:Row[]=result.rows||[]
   for(const response of details){const debt=response.data,at=options.findIndex(d=>String(d.id)===String(debt.id));if(at<0)options.unshift(debt);else options[at]=debt}
   debts.value=options
  }
 }catch(e){if(active())debtError.value='原欠料加载失败：'+message(e)}finally{if(active())debtLoading.value=false}
}
async function loadIssueLines(){
 if(issueLoading.value||!visible.value)return
 const round=++issueEpoch,session=loadEpoch,current=context(),executionId=props.executionId,type=props.type
 const active=()=>round===issueEpoch&&session===loadEpoch&&current===context()&&executionId===props.executionId&&type===props.type&&visible.value
 issueLoading.value=true
 try{
  if(!executionId)throw Error('请先选择加工批次')
  const r:any=await request({url:'/metal/storage-orders/options',params:{factoryId:state.factoryId,type,executionId},quiet:true})
  if(active()){issueLines.value=r.data?.issueLines||[];issueError.value=''}
 }catch(e){if(active())issueError.value='原领料明细加载失败：'+message(e)}
 finally{if(active())issueLoading.value=false}
}
function selectIssue(){const issue=issueLines.value.find(r=>r.id===line.value.issueLineId);if(issue){line.value.stockId=String(issue.stockId);selectStock()}}
function groupLabel(group:ReturnType<typeof stockGroups>[number]){const identity=group.members[0].stock.identity||{},details=[identity.specification,identity.purity?`${identity.purity}%`:'',identity.processName].filter(Boolean);return [`【${stockCategories[group.category]}】${group.ownerName}${group.companyName?'｜'+group.companyName:''}`,group.code,group.name,...details,`可用${weightText(group.weight)}g${group.measurementMode==='PIECE'?' / '+group.quantity+'件':''}`].join(' / ')}
function selectGroup(){const group=selectedGroup.value;if(!group)return;line.value.stockId=String(group.members[0].stock.id);selectStock();line.value.selectionOwnerId=group.ownerId;line.value.selectionOwnerName=group.ownerName;line.value.selectionCompanyName=group.companyName;line.value.selectionKey=group.key}
function selectStock(){const s=stock.value;if(s)Object.assign(line.value,{category:s.category,code:s.identity?.code||s.code,name:s.identity?.name||s.identity?.materialType||s.name||s.materialType,materialId:s.materialId,productId:s.productId,form:s.identity?.form,batchNo:s.batchNo,measurementMode:s.measurementMode,allocations:[]})}
function selectProduct(){const product=state.products.find(p=>String(p.id)===String(line.value.productId));if(product)Object.assign(line.value,{code:product.code,name:product.name})}
function selectMaterial(){const m=material.value;Object.assign(line.value,{code:m?.code,name:m?.name||m?.materialType,form:m?.materialForm||''})}
async function close(done?:()=>void){if(customerOpen.value||saving.value||props.reservationPending)return;if(JSON.stringify(line.value)!==initial){try{await ElMessageBox.confirm('放弃未保存的物料明细？','确认关闭')}catch{return}}loadEpoch++;visible.value=false;done?.()}
async function save(){if(saving.value||props.reservationPending)return;if(issueLoading.value||issueError.value||debtLoading.value||debtError.value)return;error.value='';if(['SEMI_IN','PRODUCT_IN','EXTERNAL_SEMI_IN'].includes(props.type))selectProduct();if(groupedPicking.value&&!selectedGroup.value){error.value='请选择当前客户有效库存';return}if(usesStock.value&&!stock.value||!usesStock.value&&!material.value&&!line.value.productId){error.value='请选择本厂有效物料或库存';return}if(!measurement.value){error.value='该物料未配置计量方式，请先维护基础配置';return}if(props.type==='ADJUSTMENT'){if(!/^-?\d{1,14}(\.\d{1,2})?$/.test(line.value.deltaWeight)||!line.value.remark.trim()){error.value='请填写合法调整增减值及原因';return}line.value.reason=line.value.remark;if(measurement.value==='PIECE'&&!/^-?\d+$/.test(String(line.value.deltaQuantity??''))){error.value='请填写整数件数增减';return}}else if(!decimalValid(line.value.netWeight,true)||Number(line.value.netWeight)<=0||measurement.value==='PIECE'&&!quantityValid(line.value.quantity)){error.value='净重须大于0且最多两位小数，按件物料须填写正整数件数';return}if(props.type==='EXTERNAL_SEMI_IN'&&(!line.value.externalSource?.sourceReference?.trim()||!line.value.externalSource?.completedProcessIds?.length)){error.value='请填写外部来源凭证与已完成阶段';return}if(props.type==='PRODUCT_IN'&&measurement.value==='WEIGHT'&&!quantityValid(line.value.referenceQuantity)){error.value='请填写正整数参考完工件数';return}if(!optionalPurityValid(line.value.purity)){error.value=purityError;return}if(['RAW_RETURN','RECOVERY_RETURN'].includes(props.type)&&!issueLines.value.some(r=>String(r.id)===String(line.value.issueLineId))){error.value='请选择本批有效的原领料明细';return}if(props.type==='OWNERSHIP_RETURN'&&(!line.value.debtAllocations.length||line.value.debtAllocations.some((d:any)=>!d.debtId||!decimalValid(d.weight,true)||Number(d.weight)<=0))){error.value='请填写原欠料及本次归还数量';return}if(props.type==='OWNERSHIP_RETURN'){
 const allocations=line.value.debtAllocations
 if(measurement.value==='PIECE'&&allocations.some((d:any)=>!quantityValid(d.quantity))){error.value='请填写每笔原欠料的归还整件数';return}
 const cents=(value:unknown)=>BigInt(roundDecimal(value).replace('.',''))
 const allocated=allocations.reduce((sum:bigint,d:any)=>sum+cents(d.weight),0n)
 const allocatedQuantity=allocations.reduce((sum:bigint,d:any)=>sum+BigInt(d.quantity||0),0n)
 if(allocated!==cents(line.value.netWeight)||allocatedQuantity!==BigInt(measurement.value==='PIECE'?line.value.quantity:0)){error.value='归还核销明细合计必须与单据净重、件数一致';return}
 }if(props.type==='PRODUCTION_OUT'&&!groupedPicking.value&&line.value.allocations.some((a:any)=>!sourceOwners.value.some((o:any)=>o.id===String(a.ownerId)&&!o.disabled))){error.value='请选择当前库存批次有可用余额的料权来源';return}if(line.value.allocations.some((a:any)=>a.ownerId==null||String(a.ownerId)===''||!decimalValid(a.weight,true)||Number(a.weight)<=0)){error.value='请补齐每项领料来源及重量';return}if(props.type==='ADJUSTMENT')line.value.ownerName=String(line.value.ownerId)==='0'?'工厂自有':state.customers.find(c=>String(c.id)===String(line.value.ownerId))?.name;if(props.type!=='ADJUSTMENT')line.value.netWeight=format(line.value.netWeight);line.value.measurementMode=measurement.value;if(measurement.value==='WEIGHT')line.value.quantity=null;saving.value=true;try{if(groupedPicking.value&&selectedGroup.value){if(!props.confirmGroup)throw Error('当前入口不支持合并领料，请重新打开单据');const parts=splitStockGroup(selectedGroup.value,clone(line.value),uid);await props.confirmGroup(parts,line.value.selectionGroupId||line.value.localId)}else if(props.confirmLine)await props.confirmLine(clone(line.value));else emit('save',clone(line.value));loadEpoch++;visible.value=false}catch(e){error.value=message(e)}finally{saving.value=false}}
defineExpose({open})
</script><style scoped>.owner-control{display:flex;align-items:center;gap:10px;width:100%;min-width:0}.owner-control .el-select{flex:1;min-width:0;width:0}.owner-control .el-button{flex:none;margin:0;height:32px}.material-line-dialog :deep(.el-form-item){margin-bottom:20px}.material-line-dialog :deep(.el-form-item__label){font-size:14px;font-weight:600}.material-line-dialog :deep(.el-input__inner){text-align:left}.issue-load-error{display:flex;align-items:center;gap:12px;margin-top:12px}.issue-load-error .el-alert{flex:1}.el-select{width:100%}p{color:#909399;font-size:13px}.allocation-section{margin-top:8px;padding:16px;border:1px solid #e2e8f0;border-radius:6px;background:#f8fafc}.allocation-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.allocation-heading h3{border:0;padding:0;margin:0;font-size:14px;font-weight:600}.allocation-add{margin-top:8px}.allocation-table{margin-top:14px}.allocation-table :deep(.el-table__cell){padding:10px 0}.allocation-table :deep(.cell){padding:0 12px}.allocation-table :deep(.el-input__inner){text-align:left}</style>
